import{_ as r,l as i,o as e,c as l,v as t,p as n,x as o,d as p,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"自举","description":"","frontmatter":{"title":"自举","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bootstrapping.md","filePath":"cs/bootstrapping.md","lastUpdated":1789023840000}'),d={name:"cs/bootstrapping.md"};function m(_,a,f,u,T,g){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="自举" tabindex="-1">自举 <a class="header-anchor" href="#自举" aria-label="Permalink to &quot;自举&quot;">​</a></h1><div class="epigraph"><p>用已有编译器编译新编译器的源，再用新编译器编译自己，直到二进制不动点。信任问题：第一份二进制从哪来。</p><footer>—— 据 Thompson, Reflections on Trusting Trust, 1984；Wirth 自举传统；对照 CompCert 抽取整理</footer></div><p>上一课<a href="/cs/compiler-fuzzing">Csmith</a> 测的是已得到的编译器。本课收束「程序语言与编译进阶」：缺口是<strong>自举链</strong>——Rust/GHC/Go 都用上一代编下一代。第一课 <a href="/cs/lex-flex">lex/flex</a> 从 word RAM 转入生成器；现在回到信任基。下一课程操作系统进阶从 <a href="/cs/fat-filesystem">FAT</a> 起，不在本课打开 VFS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新语言没有编译器。阶段：用 C 写一个子集编译器，再扩展，直到能编自己。不动点：<code>cc_new(src) == cc_old(src)</code> 的二进制（或 ABI 允许的等价）。缺口是<strong>阶段与信任</strong>，不是差分测试。</p><p>Thompson：编译器可插入后门且自复制，源码审计不够。对策：多样编译器比较、从更小信任基重建（Guix 引导点名）。</p><h3 id="自举不是「递归函数」" tabindex="-1">自举不是「递归函数」 <a class="header-anchor" href="#自举不是「递归函数」" aria-label="Permalink to &quot;自举不是「递归函数」&quot;">​</a></h3><p>是工程过程，不是 \\(Y\\) 组合子。不要和<a href="/cs/recursion-theorem">递归定理</a> 混为一谈，尽管都有「自己谈自己」。</p><p><span class="marginnote">Thompson 1984 Turing 演讲。GHC stage。Rust bootstrap。CompCert 用 Coq 抽取，信任核不同。本课不写完整可引导发行版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保留 stage0 二进制。stage1：stage0 编源。stage2：stage1 再编，应与 stage1 输出一致（或可解释的差异：路径嵌入）。交叉自举：用三元组在主机上为 target 产出。</p>',11)),(e(),n(h,null,{default:o(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22stage0%20%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20S1%5B%22%E7%BC%96%E8%AF%91%E6%BA%90%20%E2%86%92%20stage1%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%86%8D%E7%BC%96%E8%AF%91%20%E2%86%92%20stage2%22%5D%0A%20%20S2%20--%3E%20FIX%5B%22%E6%AF%94%E8%BE%83%20%2F%20%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 LTO/PGO：自举配置要钉死，否则二进制永远不等。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时间戳、随机、<code>__DATE__</code> 破坏可复现。可复现构建是自举验证的朋友。不要在自举时混主机头文件——<a href="/cs/cross-compile-triple">交叉</a>。</p><p>多样复现：两份无关编译器编同一源，比 Thompson 后门。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核引导。后课默认：语言实现靠自举链；信任可被 Thompson 攻击，需多样重建。程序语言与编译进阶到此结束；下一课 <a href="/cs/fat-filesystem">FAT</a>。</p><p>也不把自举当生物课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自举：用编译器编译自己，直到二进制稳定。</li><li>Thompson：恶意编译器可存活在二进制里。</li><li>与 CompCert/Csmith：证明、测试、信任链三条腿。</li><li>出处：Thompson, 1984；对照 Leroy、Yang et al.；GNU/LLVM 自举实践。</li></ul>',9))])}const C=r(d,[["render",m]]);export{A as __pageData,C as default};
